class VaultCollector:
    """Collect secrets from HashiCorp Vault"""

    def __init__(self, vault_addr: Optional[str] = None, vault_token: Optional[str] = None):
        self.vault_addr = vault_addr or os.getenv('VAULT_ADDR', 'http://localhost:8200')
        self.vault_token = vault_token or os.getenv('VAULT_TOKEN')

        if not self.vault_token:
            raise ValueError("VAULT_TOKEN environment variable is required")

        self.client = hvac.Client(url=self.vault_addr, token=self.vault_token)

    def list_secrets_recursive(self, path: str = "", engine: str = "secret") -> List[str]:
        """Recursively list all secret paths"""
        secrets = []

        try:
            # List secrets at current path
            list_path = f"{engine}/{path}" if path else engine
            response = self.client.secrets.kv.v2.list_secrets(path=path, mount_point=engine)

            if response and 'data' in response and 'keys' in response['data']:
                for key in response['data']['keys']:
                    full_path = f"{path}/{key}" if path else key

                    if key.endswith('/'):
                        # Recursively list subdirectories
                        sub_secrets = self.list_secrets_recursive(full_path.rstrip('/'), engine)
                        secrets.extend(sub_secrets)
                    else:
                        secrets.append(full_path)

        except Exception as e:
            logger.warning(f"Failed to list secrets at {path}: {e}")

        return secrets

    def read_secret(self, path: str, engine: str = "secret") -> Optional[Dict[str, Any]]:
        """Read a secret from Vault"""
        try:
            response = self.client.secrets.kv.v2.read_secret(path=path, mount_point=engine)
            if response and 'data' in response and 'data' in response['data']:
                return response['data']['data']
        except Exception as e:
            logger.warning(f"Failed to read secret {path}: {e}")
        return None

    def collect_all_secrets(self) -> Dict[str, Any]:
        """Collect all secrets from all KV v2 engines"""
        results = {
            "vault_secrets": {},
            "metadata": {
                "vault_addr": self.vault_addr,
                "collection_time": datetime.utcnow().isoformat(),
                "engine_count": 0,
                "secret_count": 0
            }
        }

        try:
            # List all mounted secret engines
            sys_info = self.client.sys.list_mounted_secrets_engines()

            for engine_path, engine_info in sys_info.get('data', {}).items():
                if engine_info.get('type') == 'kv' and engine_info.get('options', {}).get('version') == '2':
                    engine_name = engine_path.rstrip('/')
                    logger.info(f"Processing KV v2 engine: {engine_name}")

                    # List all secrets in this engine
                    secrets_list = self.list_secrets_recursive(engine=engine_name)

                    engine_secrets = {}
                    for secret_path in secrets_list:
                        secret_data = self.read_secret(secret_path, engine=engine_name)
                        if secret_data:
                            engine_secrets[secret_path] = secret_data
                            results["metadata"]["secret_count"] += 1

                    if engine_secrets:
                        results["vault_secrets"][engine_name] = engine_secrets
                        results["metadata"]["engine_count"] += 1

        except Exception as e:
            logger.error(f"Failed to collect Vault secrets: {e}")
            results["error"] = str(e)

        return results

