## State File Analysis Script (Educational)

```python
#!/usr/bin/env python3
"""
EDUCATIONAL DEMONSTRATION ONLY - For HashiCorp Security Advisory
This script demonstrates how Terraform state files can be read programmatically.
For official security testing only in controlled environments.
"""

import json
import hcl2
import requests
from typing import Dict, Any
import sys

class StateFileAnalyzer:
    """Demonstrates state file structure analysis"""

    def __init__(self, state_file_path: str):
        self.state_file_path = state_file_path
        self.sensitive_patterns = [
            'password', 'secret', 'token', 'key', 
            'credential', 'private', 'endpoint', 'connection_string'
        ]

    def load_state_file(self) -> Dict[str, Any]:
        """Load and parse Terraform state file"""
        try:
            with open(self.state_file_path, 'r') as f:
                return json.load(f)
        except FileNotFoundError:
            print(f"State file not found: {self.state_file_path}")
            sys.exit(1)
        except json.JSONDecodeError:
            print("Invalid JSON in state file")
            sys.exit(1)

    def find_sensitive_data(self, state_data: Dict[str, Any]) -> Dict[str, Any]:
        """Identify potentially sensitive data in state file"""
        sensitive_findings = {
            'outputs': {},
            'resources': [],
            'sensitive_values_found': 0
        }

        # Check outputs
        if 'outputs' in state_data:
            for output_name, output_data in state_data['outputs'].items():
                if output_data.get('sensitive', False):
                    sensitive_findings['outputs'][output_name] = {
                        'value': '[SENSITIVE - REDACTED]',
                        'type': 'sensitive_output'
                    }
                    sensitive_findings['sensitive_values_found'] += 1

        # Check resource attributes
        if 'resources' in state_data:
            for resource in state_data['resources']:
                resource_sensitive = False
                sensitive_attrs = []

                if 'instances' in resource:
                    for instance in resource['instances']:
                        if 'attributes' in instance:
                            for attr_name, attr_value in instance['attributes'].items():
                                if any(pattern in attr_name.lower() 
                                       for pattern in self.sensitive_patterns):
                                    sensitive_attrs.append(attr_name)
                                    resource_sensitive = True
                                    sensitive_findings['sensitive_values_found'] += 1

                if resource_sensitive:
                    sensitive_findings['resources'].append({
                        'type': resource.get('type', 'unknown'),
                        'name': resource.get('name', 'unknown'),
                        'sensitive_attributes': sensitive_attrs
                    })

        return sensitive_findings

    def generate_report(self, findings: Dict[str, Any]) -> str:
        """Generate a security report"""
        report = f"""
        ============================================
        TERRAFORM STATE FILE SECURITY ANALYSIS
        ============================================

        State File: {self.state_file_path}
        Sensitive Values Found: {findings['sensitive_values_found']}

        SENSITIVE OUTPUTS:
        {json.dumps(findings['outputs'], indent=2)}

        RESOURCES WITH SENSITIVE ATTRIBUTES:
        {json.dumps(findings['resources'], indent=2)}

        RECOMMENDATIONS:
        1. Always mark sensitive outputs with 'sensitive = true'
        2. Use environment variables or secret managers for credentials
        3. Restrict state file access with proper IAM policies
        4. Enable state file encryption
        5. Use Terraform Cloud/Enterprise with access controls
        ============================================
        """
        return report

def main():
    """Main function for demonstration"""
    print("""
    ⚠️  EDUCATIONAL DEMONSTRATION ONLY ⚠️
    This script is for HashiCorp Security Advisory purposes.
    Use only in authorized, controlled testing environments.
    """)

    # Example usage - replace with your actual state file
    analyzer = StateFileAnalyzer("terraform.tfstate")

    # Load state file
    state_data = analyzer.load_state_file()

    # Analyze for sensitive data
    findings = analyzer.find_sensitive_data(state_data)

    # Generate report
    report = analyzer.generate_report(findings)
    print(report)

    # In a real security test, you would:
    # 1. Use Terraform Cloud API with proper authentication
    # 2. Access only authorized workspaces
    # 3. Never exfiltrate actual sensitive data
    # 4. Use dummy/test data only

if __name__ == "__main__":
    main()
```

