## 1. Main Pipeline Template (`vars/pipelineTemplate.groovy`)

```groovy
#!/usr/bin/env groovy

def call(Map config = [:]) {
    pipeline {
        agent any

        options {
            buildDiscarder(logRotator(numToKeepStr: '10'))
            disableConcurrentBuilds()
            timeout(time: 30, unit: 'MINUTES')
        }

        environment {
            // Environment-specific configurations
            ENVIRONMENT = "${env.BRANCH_NAME == 'main' ? 'production' : 'staging'}"
            DOCKER_REGISTRY = credentials('docker-registry-creds')
            HELM_REPO = 'https://charts.company.com'
            AUDIT_ENDPOINT = 'https://jenkins-audit.internal/health'

            // Load environment-specific config
            CONFIG_FILE = "config/${ENVIRONMENT}.yaml"
        }

        stages {
            stage('Initialize') {
                steps {
                    script {
                        // Load environment config
                        loadEnvironmentConfig()

                        // Run credentials health check
                        credentialsHealthCheck()
                    }
                }
            }

            stage('Checkout & Version Bump') {
                steps {
                    checkout scm
                    script {
                        // Automated version bump based on conventional commits
                        def newVersion = versionBump()
                        env.APP_VERSION = newVersion
                    }
                }
            }

            stage('Build & Test') {
                steps {
                    script {
                        sh """
                            docker build -t ${env.DOCKER_REGISTRY}/app:${env.APP_VERSION} .
                            docker run --rm ${env.DOCKER_REGISTRY}/app:${env.APP_VERSION} npm test
                        """
                    }
                }
            }

            stage('Sign Artifact') {
                steps {
                    script {
                        // Sign Docker image with GPG
                        withCredentials([file(credentialsId: 'gpg-private-key', variable: 'GPG_KEY')]) {
                            sh """
                                gpg --import ${GPG_KEY}
                                docker trust sign ${env.DOCKER_REGISTRY}/app:${env.APP_VERSION}
                            """
                        }
                    }
                }
            }

            stage('Push Artifact') {
                steps {
                    script {
                        sh "docker push ${env.DOCKER_REGISTRY}/app:${env.APP_VERSION}"
                    }
                }
            }

            stage('Deploy to Kubernetes') {
                steps {
                    script {
                        deployToKubernetes(
                            environment: ENVIRONMENT,
                            version: env.APP_VERSION,
                            namespace: "app-${ENVIRONMENT}"
                        )
                    }
                }
            }

            stage('Canary Analysis') {
                steps {
                    script {
                        canaryAnalysis(
                            namespace: "app-${ENVIRONMENT}",
                            duration: '5m',
                            metricsEndpoint: "http://app.${ENVIRONMENT}.company.com/metrics"
                        )
                    }
                }
            }

            stage('Cleanup') {
                when {
                    expression { ENVIRONMENT == 'staging' }
                }
                steps {
                    script {
                        sh "kubectl delete namespace app-staging --wait=true --timeout=300s"
                    }
                }
            }
        }

        post {
            always {
                cleanWs()
            }
            success {
                script {
                    slackSend(
                        color: 'good',
                        message: "Pipeline ${env.JOB_NAME} #${env.BUILD_NUMBER} succeeded"
                    )
                }
            }
            failure {
                script {
                    slackSend(
                        color: 'danger',
                        message: "Pipeline ${env.JOB_NAME} #${env.BUILD_NUMBER} failed"
                    )
                }
            }
        }
    }
}

def loadEnvironmentConfig() {
    def config = readYaml file: env.CONFIG_FILE
    env.KUBERNETES_CLUSTER = config.kubernetes.cluster
    env.HELM_CHART_VERSION = config.helm.version
    env.REPLICA_COUNT = config.deployment.replicas
    env.RESOURCE_LIMITS = config.deployment.resources
}
