## 2. Version Bumping (`vars/versionBump.groovy`)

```groovy
#!/usr/bin/env groovy

import com.company.jenkins.VersionManager

def call() {
    def versionManager = new VersionManager()

    // Get commit messages since last tag
    def commitMessages = sh(
        script: 'git log --oneline $(git describe --tags --abbrev=0 2>/dev/null || echo "HEAD~10")..HEAD',
        returnStdout: true
    ).trim()

    // Determine version bump type based on conventional commits
    def bumpType = determineBumpType(commitMessages)

    // Read current version from package.json or similar
    def currentVersion = readJSON(file: 'package.json').version

    // Calculate new version
    def newVersion = versionManager.calculateNewVersion(currentVersion, bumpType)

    // Update version files
    sh """
        npm version ${newVersion} --no-git-tag-version
        sed -i 's/version: .*/version: ${newVersion}/' Chart.yaml
    """

    // Create git tag
    sh """
        git add package.json Chart.yaml
        git commit -m "chore: bump version to ${newVersion}"
        git tag -a v${newVersion} -m "Release v${newVersion}"
        git push origin v${newVersion}
    """

    return newVersion
}

def determineBumpType(String commitMessages) {
    def lines = commitMessages.split('\n')

    def hasBreakingChange = lines.any { it =~ /^[a-f0-9]+.*(BREAKING CHANGE|!):/ }
    def hasFeature = lines.any { it =~ /^[a-f0-9]+.*feat(\(.*\))?:/ }

    if (hasBreakingChange) {
        return 'major'
    } else if (hasFeature) {
        return 'minor'
    } else {
        return 'patch'
    }
}
```

## 3. Credentials Health Check (`vars/credentialsHealthCheck.groovy`)

```groovy
#!/usr/bin/env groovy

import com.company.jenkins.CredentialsAuditor
import jenkins.model.Jenkins
import com.cloudbees.plugins.credentials.CredentialsProvider
import com.cloudbees.plugins.credentials.domains.Domain

def call() {
    def auditor = new CredentialsAuditor()

    echo "Starting credentials health check..."

    // Get all credentials
    def allCredentials = CredentialsProvider.lookupCredentials(
        com.cloudbees.plugins.credentials.Credentials.class,
        Jenkins.instance,
        null,
        null
    )

    def results = []

    allCredentials.each { cred ->
        try {
            def healthCheck = auditor.checkCredentialHealth(cred)
            results.add(healthCheck)

            // Log to audit endpoint
            auditor.logToAuditEndpoint(
                credentialId: cred.id,
                type: cred.class.simpleName,
                status: healthCheck.status,
                message: healthCheck.message,
                timestamp: new Date().toString()
            )

            if (healthCheck.status != 'HEALTHY') {
                echo "WARNING: Credential ${cred.id} - ${healthCheck.message}"
            }

        } catch (Exception e) {
            echo "ERROR checking credential ${cred.id}: ${e.message}"
        }
    }

    // Generate report
    def healthyCount = results.count { it.status == 'HEALTHY' }
    def warningCount = results.count { it.status == 'WARNING' }
    def errorCount = results.count { it.status == 'ERROR' }

    echo """
    ===== CREDENTIALS HEALTH CHECK REPORT =====
    Total Credentials: ${results.size()}
    Healthy: ${healthyCount}
    Warnings: ${warningCount}
    Errors: ${errorCount}
    ===========================================
    """

    if (errorCount > 0) {
        error("Credentials health check failed with ${errorCount} errors")
    }
}
