### `main.tf`
```hcl
module "organization" {
  source = "./modules/organization"

  management_account_id = var.management_account_id
  member_accounts       = var.member_accounts
  allowed_regions       = var.allowed_regions
}

module "control_tower" {
  count  = var.enable_control_tower ? 1 : 0
  source = "./modules/control-tower"

  management_account_id = var.management_account_id
  audit_account_id      = var.audit_account_id
  log_archive_account_id = var.log_archive_account_id
  region                = var.aws_region
}

module "logging" {
  source = "./modules/logging"

  providers = {
    aws.management   = aws.management
    aws.log_archive  = aws.log_archive
  }

  management_account_id = var.management_account_id
  log_archive_account_id = var.log_archive_account_id
  organization_id       = module.organization.organization_id
}

module "security" {
  source = "./modules/security"

  providers = {
    aws.management = aws.management
    aws.audit      = aws.audit
  }

  management_account_id = var.management_account_id
  audit_account_id      = var.audit_account_id
  security_hub_standards = var.security_hub_standards
  organization_id       = module.organization.organization_id
}

module "identity_center" {
  source = "./modules/identity-center"

  providers = {
    aws.management = aws.management
  }

  management_account_id = var.management_account_id
  identity_store_id     = module.control_tower[0].identity_store_id
}

module "compliance_auditor" {
  source = "./modules/compliance-auditor"

  providers = {
    aws.management = aws.management
  }

  for_each = var.member_accounts

  account_id                 = each.value.account_id
  account_name               = each.value.name
  compliance_dashboard_sns_arn = var.compliance_dashboard_sns_arn
  management_account_id      = var.management_account_id
}
