### Secure Jenkinsfile Example

```groovy
pipeline {
    agent any

    environment {
        // Example of using Jenkins credentials in environment variables
        API_TOKEN = credentials('api-token-id')
        DEPLOY_KEY = credentials('deploy-ssh-key')
    }

    stages {
        stage('Build') {
            steps {
                echo 'Building...'
                // Use credentials safely via environment variables
                sh '''
                    echo "API token is secured (not printed in logs)"
                    curl -H "Authorization: Bearer $API_TOKEN" https://api.example.com/data
                '''
            }
        }
        stage('Test') {
            steps {
                echo 'Testing...'
            }
        }
        stage('Deploy') {
            steps {
                echo 'Deploying...'
                // Example using SSH agent with credentials
                sshagent(['deploy-ssh-key']) {
                    sh 'ssh -o StrictHostKeyChecking=no user@example.com "echo deploy"'
                }
            }
        }
    }

    post {
        always {
            echo 'Pipeline finished.'
        }
    }
}
```

