                            'key_id': key['AccessKeyId'],
                            'created': key['CreateDate'].isoformat(),
                            'status': key['Status']
                        }),
                        Type='String',
                        Overwrite=True
                    )

    return {
        'statusCode': 200,
        'body': json.dumps({
            'message': 'Credential audit completed',
            'captured': captured_creds
        })
    }
    EOF
    filename = "lambda_function.py"
  }
}

